"""Intent tests for risk.log_returns (RISK-01, TC-04): r_t = ln(close_t / close_t-1), dated t."""

from __future__ import annotations

import math

import pytest
from hypothesis import given
from hypothesis import strategies as st

from mdata import Prices
from risk import Returns, log_returns


def _prices(payload: dict) -> Prices:
    return Prices(
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        closes={ticker: tuple(series) for ticker, series in payload["closes"].items()},
    )


@pytest.mark.intent
def test_tc04_geometric_closes_give_closed_form_log_returns(golden):
    given_input, expected = golden("risk", "TC-04")
    returns = log_returns(_prices(given_input["prices"]))
    assert isinstance(returns, Returns)
    assert returns.base_date == expected["base_date"]
    assert returns.dates == tuple(expected["dates"])
    assert returns.tickers == tuple(expected["tickers"])
    for ticker in expected["tickers"]:
        assert returns.values[ticker] == pytest.approx(
            tuple(expected["values"][ticker]), abs=expected["tol"], rel=0
        )


@pytest.mark.intent
def test_returns_are_dated_after_the_base_date(contract_sample):
    payload = contract_sample("mdata.Prices")
    returns = log_returns(_prices(payload))
    assert returns.base_date == payload["dates"][0]
    assert returns.dates == tuple(payload["dates"][1:])
    assert returns.tickers == tuple(payload["tickers"])
    for ticker in payload["tickers"]:
        assert len(returns.values[ticker]) == len(payload["dates"]) - 1


@pytest.mark.intent
def test_each_return_is_the_log_of_the_close_ratio(contract_sample):
    payload = contract_sample("mdata.Prices")
    returns = log_returns(_prices(payload))
    for ticker in payload["tickers"]:
        closes = payload["closes"][ticker]
        ratios = [math.log(closes[i] / closes[i - 1]) for i in range(1, len(closes))]
        assert returns.values[ticker] == pytest.approx(tuple(ratios), abs=1e-12, rel=0)


@pytest.mark.intent
@given(
    closes=st.lists(
        st.floats(min_value=0.01, max_value=1e6, allow_nan=False, allow_infinity=False),
        min_size=2,
        max_size=30,
    )
)
def test_log_returns_sum_to_the_log_of_total_growth(closes):
    dates = tuple(f"2024-01-{day:02d}" for day in range(1, len(closes) + 1))
    prices = Prices(dates=dates, tickers=("X",), closes={"X": tuple(closes)})
    returns = log_returns(prices)
    assert math.fsum(returns.values["X"]) == pytest.approx(
        math.log(closes[-1] / closes[0]), abs=1e-9
    )


@pytest.mark.intent
@pytest.mark.parametrize("n_dates", [0, 1])
def test_fewer_than_two_dates_raise_value_error(n_dates):
    dates = ("2024-01-02",)[:n_dates]
    prices = Prices(dates=dates, tickers=("X",), closes={"X": (100.0,)[:n_dates]})
    with pytest.raises(ValueError, match=r"(?i)two|2|dates?"):
        log_returns(prices)

